// Surah names + ayah counts (Hafs).
//
// SOURCE: copied verbatim from the `surahs` table of the main Tilawa
// app's own verified Quran database
// (~/workspace/tilawa/phase1/fts/quran_apk.db — the database shipped in
// Tilawa v1.0.0). 114 rows; ayah counts sum to 6236 (verified when
// generating this file). These are NAMES ONLY — never ayah text: all
// ayah text still comes from the engine's own ref-v2.json via
// engine.passageWords(). The short display names (name_short) are used,
// e.g. «الفاتحة» instead of the full «سُورَةُ ٱلْفَاتِحَةِ».
//
// Do NOT edit by hand: regenerate from the database if it ever changes.

/// Short display name of surah [number] (1..114), e.g. «الفاتحة».
String surahName(int number) => _kSurahNames[number - 1];

/// Number of ayahs in surah [number] (Hafs), e.g. 7 for Al-Fatiha.
int surahAyahCount(int number) => _kSurahAyahCounts[number - 1];

/// True when [number] is a valid surah number (1..114).
bool isValidSurah(int number) => number >= 1 && number <= 114;

